def parse_env(text):
    """Reads KEY=value lines into a dict.

    Blank lines and lines starting with '#' are skipped. Only the first '='
    splits key from value. One pair of matching single or double quotes
    around a value is removed.
    """
    settings = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            continue
        key, value = line.split("=", 1)
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
            value = value[1:-1]
        settings[key.strip()] = value
    return settings

files.tests/test_envfile.py:
from envfile import parse_env


def test_reads_pairs():
    assert parse_env("A=1\nB=two") == {"A": "1", "B": "two"}


def test_skips_empty_lines():
    assert parse_env("A=1\n\nB=2") == {"A": "1", "B": "2"}


def test_skips_comment_lines():
    assert parse_env("# database\nA=1") == {"A": "1"}


def test_strips_matching_quotes():
    assert parse_env("A=\"x y\"\nB='z'") == {"A": "x y", "B": "z"}


def test_keeps_mismatched_quotes():
    assert parse_env("A=\"x'") == {"A": "\"x'"}


def test_keeps_equals_in_value():
    assert parse_env('URL="a=b"') == {"URL": "a=b"}

